}

import XCTest

final class TapRunnerUITests: XCTestCase {
    func testOpenOwnProfile() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 3) {
            openButton.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        if !app.waitForExistence(timeout: 15) {
            app.launch()
        }
        if app.state != .runningForeground {
            app.activate()
        }
        Thread.sleep(forTimeInterval: 3)

        var tapped = false
        let candidates = [
            app.tabBars.firstMatch.buttons["Profile"],
            app.buttons["Profile"],
        ]
        for c in candidates {
            if c.waitForExistence(timeout: 2) {
                c.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.878, dy: 0.882)).tap()
        }
        Thread.sleep(forTimeInterval: 3)
    }
}

import XCTest

final class TapRunnerUITests: XCTestCase {
    func testOpenOwnProfile() throws {
        addUIInterruptionMonitor(withDescription: "Open in Bluesky alert") { (interruptingApp) -> Bool in
            let open = interruptingApp.buttons["Open"]
            if open.exists {
                open.tap()
                return true
            }
            return false
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        if !app.waitForExistence(timeout: 15) {
            app.launch()
        }
        app.activate()

        let launcherMarker = app.staticTexts["Enter URL manually"]
        if launcherMarker.waitForExistence(timeout: 5) {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.315)).tap()
        }

        let deadline = Date().addingTimeInterval(60)
        while launcherMarker.exists && Date() < deadline {
            Thread.sleep(forTimeInterval: 1)
        }
        Thread.sleep(forTimeInterval: 3)

        var tapped = false
        let candidates = [
            app.tabBars.firstMatch.buttons["Profile"],
            app.buttons["Profile"],
        ]
        for c in candidates {
            if c.waitForExistence(timeout: 2) {
                c.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.878, dy: 0.882)).tap()
        }
        Thread.sleep(forTimeInterval: 3)
    }
}
